//! Application logic shared by the desktop app (Tauri commands) and the `sb` CLI.
//! Free of any UI type so it can be unit-tested without a window.

use std::fs;
use std::path::Path;

use sb_codegen::{CodegenError, GeneratedFile};
use sb_model::{Diagnostic, Project, SCHEMA_VERSION, Severity, has_errors};
use serde::Serialize;

/// Marker written at the top of every generated file; used to recognise our own exports.
const GENERATED_MARKER: &str = "@generated by service-builder";

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct Analysis {
    pub diagnostics: Vec<Diagnostic>,
    /// Empty when the project has errors.
    pub files: Vec<GeneratedFile>,
}

/// Validates the project and, when it is error free, generates (and formats) the code.
pub fn analyze(project: &Project) -> Analysis {
    let diagnostics = sb_codegen::diagnose(project);
    if has_errors(&diagnostics) {
        return Analysis {
            diagnostics,
            files: vec![],
        };
    }
    match sb_codegen::generate(project) {
        Ok(mut files) => {
            sb_codegen::rustfmt(&mut files);
            Analysis { diagnostics, files }
        }
        Err(e) => {
            let mut diagnostics = match &e {
                CodegenError::Invalid(d) => d.clone(),
                CodegenError::Internal(_) => diagnostics,
            };
            if let CodegenError::Internal(msg) = e {
                diagnostics.push(Diagnostic {
                    severity: Severity::Error,
                    code: "E_INTERNAL".into(),
                    message: msg,
                    path: String::new(),
                });
            }
            Analysis {
                diagnostics,
                files: vec![],
            }
        }
    }
}

pub fn load_project(path: &Path) -> Result<Project, String> {
    let text =
        fs::read_to_string(path).map_err(|e| format!("cannot read {}: {e}", path.display()))?;
    let mut project: Project = serde_json::from_str(&text)
        .map_err(|e| format!("{} is not a valid project: {e}", path.display()))?;
    if project.schema_version > SCHEMA_VERSION {
        return Err(format!(
            "{} was saved by a newer version of Service Builder (format {} > {SCHEMA_VERSION})",
            path.display(),
            project.schema_version
        ));
    }
    project.freeze_field_numbers();
    Ok(project)
}

/// Writes through a temporary file so a crash never leaves a truncated project behind.
pub fn save_project(path: &Path, project: &Project) -> Result<(), String> {
    let json = serde_json::to_string_pretty(project).map_err(|e| e.to_string())?;
    let tmp = path.with_extension("tmp");
    fs::write(&tmp, json + "\n").map_err(|e| format!("cannot write {}: {e}", tmp.display()))?;
    fs::rename(&tmp, path).map_err(|e| format!("cannot write {}: {e}", path.display()))
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ExportReport {
    pub dir: String,
    pub files: usize,
}

/// Generates the workspace into `dir`. Refuses to touch a directory that holds a Cargo
/// workspace we did not generate.
pub fn export_project(project: &Project, dir: &Path) -> Result<ExportReport, String> {
    let manifest = dir.join("Cargo.toml");
    if manifest.exists() {
        let existing = fs::read_to_string(&manifest).unwrap_or_default();
        if !existing.contains(GENERATED_MARKER) {
            return Err(format!(
                "{} already contains a Cargo.toml that was not generated by Service Builder; choose an empty folder",
                dir.display()
            ));
        }
    }
    let analysis = analyze(project);
    if analysis.files.is_empty() {
        let n = analysis
            .diagnostics
            .iter()
            .filter(|d| d.severity == Severity::Error)
            .count();
        return Err(format!(
            "the project has {n} error(s), fix them before exporting"
        ));
    }
    sb_codegen::write_to_dir(&analysis.files, dir)
        .map_err(|e| format!("cannot write to {}: {e}", dir.display()))?;
    Ok(ExportReport {
        dir: dir.display().to_string(),
        files: analysis.files.len(),
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use sb_model::sample;

    fn temp(name: &str) -> std::path::PathBuf {
        let dir = std::env::temp_dir().join(format!("sb-tauri-{name}-{}", std::process::id()));
        let _ = fs::remove_dir_all(&dir);
        fs::create_dir_all(&dir).unwrap();
        dir
    }

    #[test]
    fn analyze_valid_and_invalid() {
        let ok = analyze(&sample::orders());
        assert!(!ok.files.is_empty());
        assert!(ok.diagnostics.is_empty());

        let mut bad = sample::orders();
        bad.topics[0].message = "Nope".into();
        let bad = analyze(&bad);
        assert!(bad.files.is_empty());
        assert!(has_errors(&bad.diagnostics));
    }

    #[test]
    fn save_then_load_round_trips() {
        let dir = temp("roundtrip");
        let path = dir.join("p.sb.json");
        let project = sample::orders();
        save_project(&path, &project).unwrap();
        assert_eq!(load_project(&path).unwrap(), project);
        fs::remove_dir_all(dir).unwrap();
    }

    #[test]
    fn opening_a_project_freezes_field_numbers() {
        let dir = temp("freeze");
        let path = dir.join("p.json");
        let mut project = sample::orders();
        for f in project.messages.iter_mut().flat_map(|m| &mut m.fields) {
            f.tag = None; // as in a hand-written file
        }
        save_project(&path, &project).unwrap();
        let loaded = load_project(&path).unwrap();
        assert!(
            loaded
                .messages
                .iter()
                .flat_map(|m| &m.fields)
                .all(|f| f.tag.is_some())
        );
        // Same numbers as the generator would have chosen.
        assert_eq!(
            sb_codegen::generate(&loaded).unwrap(),
            sb_codegen::generate(&project).unwrap()
        );
        fs::remove_dir_all(dir).unwrap();
    }

    #[test]
    fn rejects_garbage_and_newer_formats() {
        let dir = temp("load");
        let path = dir.join("p.json");
        fs::write(&path, "{ nope").unwrap();
        assert!(
            load_project(&path)
                .unwrap_err()
                .contains("not a valid project")
        );

        let mut project = sample::orders();
        project.schema_version = SCHEMA_VERSION + 1;
        save_project(&path, &project).unwrap();
        assert!(load_project(&path).unwrap_err().contains("newer version"));
        assert!(
            load_project(&dir.join("missing.json"))
                .unwrap_err()
                .contains("cannot read")
        );
        fs::remove_dir_all(dir).unwrap();
    }

    #[test]
    fn export_is_repeatable_but_never_overwrites_foreign_projects() {
        let dir = temp("export");
        let report = export_project(&sample::orders(), &dir).unwrap();
        assert!(report.files > 10);
        assert!(dir.join("services/orders/src/main.rs").exists());
        // Re-exporting over our own output is fine.
        export_project(&sample::orders(), &dir).unwrap();

        fs::write(dir.join("Cargo.toml"), "[package]\nname = \"mine\"\n").unwrap();
        let err = export_project(&sample::orders(), &dir).unwrap_err();
        assert!(err.contains("not generated by Service Builder"));
        assert_eq!(
            fs::read_to_string(dir.join("Cargo.toml")).unwrap(),
            "[package]\nname = \"mine\"\n"
        );
        fs::remove_dir_all(dir).unwrap();
    }

    #[test]
    fn export_refuses_invalid_projects() {
        let dir = temp("invalid");
        let mut p = sample::orders();
        p.services[0].port = 0;
        assert!(export_project(&p, &dir).unwrap_err().contains("error(s)"));
        assert!(!dir.join("Cargo.toml").exists());
        fs::remove_dir_all(dir).unwrap();
    }
}
